def num_trainable_weights(self) -> int:
    """ Returns the number of weights. The model must have been call()ed once """
    assert not self.agent is None, "build() must be called first"
    weights = self.trainable_weights
    return np.sum( [ np.prod( w.get_shape() ) for w in weights ] )

def Extend_Bin_Data(bin_data, r):

    if np.all(r == 0):

        return(bin_data)

    sumy, binx = bin_data

    extend_range = [[k] * 2 for k in r]

    sumy = np.pad(sumy, extend_range, 'constant', constant_values = 0)

    binx = np.pad(binx, extend_range, 'constant', constant_values = 0)

    return(np.asarray([sumy, binx]))

def Get_Linear_Solve(xt, weight, bin_data_num, bin_data_y, r):

    p, n = xt.shape

    xtw = xt * weight

    n_grid = np.prod(bin_data_num.shape - (2 * r))

    s = np.zeros((p, p, n_grid))

    t = np.zeros((p, n_grid))

    for i in range(p):

        for j in range(i, p):

            if i is 0:

                kernel = xtw.take(j, 0).reshape(2 * r + 1)

                t[j] = sp.signal.fftconvolve(kernel, bin_data_y, mode = 'valid').reshape(-1)

            else:

                kernel = np.reshape(xtw.take(i, 0) * xt.take(j, 0), 2 * r + 1)

            s[i, j] = sp.signal.fftconvolve(kernel, bin_data_num, mode = 'valid').reshape(-1)

            s[j, i] = s[i, j]

    for i in range(1, p):

        s[i, i] += 1e-12

    s = s.reshape(p**2, -1).T.reshape(-1, p, p)

    try:

        fit_y = np.linalg.solve(s, t.T).take(0, 1)

    except:

        indptr = np.arange(n_grid + 1)

        indices = np.arange(n_grid)

        s_sparse = sp.sparse.bsr_matrix((s, indices, indptr), shape = (p * n_grid, p * n_grid)).tocsc()

        fit_y = sp.sparse.linalg.spsolve(s_sparse, t.T.reshape(-1))[::p]

    return(fit_y)

def Get_Linear_Equation_Gpu(x, weight, bin_data_num, bin_data_y, r, dtype = 'f4'):

    n, p = x.shape

    d = p - 1

    if dtype is 'f4':

        dtype = af.Dtype.f32

    elif dtype is 'f8':

        dtype = af.Dtype.f64

    xw = af.constant(0, n, p, dtype = dtype)

    for ii in af.ParallelRange(p):

        xw[:, ii] = x[:, ii] * weight

    s = af.constant(0, p, p, np.prod(bin_data_num.shape), dtype = dtype)

    t = af.constant(0, p, np.prod(bin_data_num.shape), dtype = dtype)

    ker_d = np.ones(4, dtype = 'int')

    ker_d[:d] = 2 * r + 1

    if d is 4:

        for i in range(p):

            for j in range(i, p):

                if i is 0:

                    kernel = af.moddims(xw[:, j], ker_d[0], ker_d[1], ker_d[2], ker_d[3])

                    t[j] = af.flat(af.reorder(Convolve4(bin_data_y, kernel), 3, 2, 1, 0))

                else:

                    kernel = af.moddims(xw[:, i] * x[:, j], ker_d[0], ker_d[1], ker_d[2], ker_d[3])

                s[i, j] = af.flat(af.reorder(Convolve4(bin_data_num, kernel), 3, 2, 1, 0))

                s[j, i] = s[i, j]

    elif d < 4:

        for i in range(p):

            for j in range(i, p):

                if i is 0:

                    kernel = af.moddims(xw[:, j], ker_d[0], ker_d[1], ker_d[2], ker_d[3])

                    if kernel.elements() is 1:

                        t[j] = af.flat((bin_data_y * kernel.to_list()[0]).T)

                    else:

                        t[j] = af.flat(af.fft_convolve(bin_data_y, kernel).T)

                else:

                    kernel = af.moddims(xw[:, i] * x[:, j], ker_d[0], ker_d[1], ker_d[2], ker_d[3])

                if kernel.elements() is 1:

                    s[i, j] = af.flat((bin_data_num * kernel.to_list()[0]).T)

                else:

                    s[i, j] = af.flat(af.fft_convolve(bin_data_num, kernel).T)

                s[j, i] = s[i, j]

    for i in range(1, p):

        s[i, i] += 1e-12

    return([np.array(s).reshape(p**2, -1).T.reshape(-1, p, p), np.array(af.flat(t))])

def agm_rob(spec: STLExp, x, t: int) -> float:
    if isinstance(spec, Tru):
        return 1.0
    if isinstance(spec, GEQ0):
        return 0.5 * spec.f(x[t])
    if isinstance(spec, LEQ0):
        return -0.5 * spec.f(x[t])
    if isinstance(spec, Neg):
        return -agm_rob(spec.e, x, t)
    if isinstance(spec, And):
        robs = np.array([agm_rob(e, x, t) for e in spec.exps])
        m = len(spec.exps)
        if np.any(robs <= 0):
            return (1.0 / m) * np.sum([np.minimum(0.0, r) for r in robs])
        else:
            return np.prod([1 + r for r in robs]) ** (1.0 / m) - 1.0
    if isinstance(spec, Or):
        left_rob = agm_rob(spec.e_1, x, t)
        right_rob = agm_rob(spec.e_2, x, t)
        m = 2.0
        if left_rob >= 0.0 or right_rob >= 0.0:
            return (1.0 / m) * np.sum([np.maximum(0, r) for r in [left_rob, right_rob]])
        else:
            return 1.0 - np.prod([1.0 - r for r in [left_rob, right_rob]]) ^ (1.0 / m)
    if isinstance(spec, G):
        new_start = t + spec.t_start
        new_end = np.minimum(t + spec.t_end + 1, len(x))
        robustness_scores = [agm_rob(spec.e, x, new_t) for new_t in range(new_start, new_end)]
        N = len(robustness_scores)
        if any([r <= 0.0 for r in robustness_scores]):
            return (1.0 / N) * np.sum([np.minimum(0.0, r) for r in robustness_scores])
        else:
            return np.prod([1.0 + r for r in robustness_scores]) ** (1.0 / N) - 1.0
    if isinstance(spec, F):
        robustness_scores = [agm_rob(spec.e, x, t + k) for k in range(spec.t_start, spec.t_end + 1)]
        N = len(robustness_scores)
        if any([r > 0.0 for r in robustness_scores]):
            return (1.0 / N) * np.sum([np.maximum(0.0, r) for r in robustness_scores])
        else:
            return 1.0 - np.prod([1.0 - r for r in robustness_scores]) ** (1 / N)
    if isinstance(spec, U):
        raise NotImplementedError("Havent yet translated the code for agm 'Until' case")

    raise ValueError(f"Invalid spec: : {spec} of type {type(spec)}")

def is_constant(item):
    """checks if node only depends on constants/shapes"""

    key = "only_involves_shapes_or_constants"
    if isinstance(item, Constant) or not isvar(item) or item is None:
        return True
    elif type(item) in [list, tuple]:
        return numpy.all([is_constant(p) for p in item])
    else:
        return False

def interpolate_poly(values, nodes):
    """Compute the interpolating polynomial for the given nodes and values in
    barycentric form.
    """
    n = len(nodes)
    if n != len(values):
        raise ValueError('input arrays should have the same length')
    x = nodes
    weights = np.array([
            1.0 / np.prod([x[i] - x[j] for j in range(n) if j != i])
            for i in range(n)
    ])
    return BarycentricRational(nodes, values, weights)

def __eq__(self, other):
    if not isinstance(other, Grid):
        return False
    return (
        numpy.all(other.grid == self.grid)
        and numpy.all(other.origin == self.origin)
        and numpy.all(
            numpy.all(other_edge == self_edge)
            for other_edge, self_edge in zip(other.edges, self.edges)
        )
    )

def num_grids(self):
    grid_shape = self.grid_shape
    batch_size = self.batch_size
    return int(np.prod((batch_size,) + grid_shape))

def check_dimensions(self, bin_edges):
    cumulative_size = numpy.cumprod([len(bin_edge) + 1 for name, bin_edge in bin_edges.items()])
    if numpy.any(cumulative_size > self.max_cells):
        raise ValueError(
            f"the total size of lookup table exceeds {self.max_cells}, reduce n_bins or number of features in use"
        )
